WITH latest_match AS (SELECT s.id, s.email, s.credit_limit, x.account_account_type, x.account_balance FROM customers s LEFT JOIN LATERAL (SELECT c.account_type AS account_account_type, c.balance AS account_balance FROM accounts c WHERE c.customer_id = s.id ORDER BY c.balance DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, email, credit_limit, account_account_type, account_balance FROM latest_match
